   462  gen_move(codegen_scope *s, uint16_t dst, uint16_t src, int nopeep)
   463  {
   464    if (no_peephole(s)) {
   465    normal:
   466      genop_2(s, OP_MOVE, dst, src);
   467      return;
   468    }
   469    else {
   470      struct mrb_insn_data data = mrb_last_insn(s);
   471
   472      switch (data.insn) {
   473      case OP_MOVE:
   474        if (dst == src) return;             /* remove useless MOVE */
   475        if (data.b == dst && data.a == src) /* skip swapping MOVE */
   476          return;
   477        goto normal;
   478      case OP_LOADNIL: case OP_LOADSELF: case OP_LOADT: case OP_LOADF:
   479      case OP_LOADI__1:
   480      case OP_LOADI_0: case OP_LOADI_1: case OP_LOADI_2: case OP_LOADI_3:
   481      case OP_LOADI_4: case OP_LOADI_5: case OP_LOADI_6: case OP_LOADI_7:
   482        if (nopeep || data.a != src || data.a < s->nlocals) goto normal;
   483        s->pc = s->lastpc;
   484        genop_1(s, data.insn, dst);
   485        break;
   486      case OP_LOADI: case OP_LOADINEG:
   487      case OP_LOADL: case OP_LOADSYM:
   488      case OP_GETGV: case OP_GETSV: case OP_GETIV: case OP_GETCV:
   489      case OP_GETCONST: case OP_STRING:
   490      case OP_LAMBDA: case OP_BLOCK: case OP_METHOD: case OP_BLKPUSH:
   491        if (nopeep || data.a != src || data.a < s->nlocals) goto normal;
   492        s->pc = s->lastpc;
   493        genop_2(s, data.insn, dst, data.b);
   494        break;
   495      default:
   496        goto normal;
   497      }
   498    }
   499  }
