  1186  gen_call(codegen_scope *s, node *tree, mrb_sym name, int sp, int val, int safe)
  1187  {
  1188    mrb_sym sym = name ? name : nsym(tree->cdr->car);
  1189    int skip = 0;
  1190    int n = 0, noop = 0, sendv = 0, blk = 0;
  1191
  1192    codegen(s, tree->car, VAL); /* receiver */
  1193    if (safe) {
  1194      int recv = cursp()-1;
  1195      gen_move(s, cursp(), recv, 1);
  1196      skip = genjmp2_0(s, OP_JMPNIL, cursp(), val);
  1197    }
  1198    tree = tree->cdr->cdr->car;
  1199    if (tree) {
  1200      n = gen_values(s, tree->car, VAL, sp?1:0);
  1201      if (n < 0) {
  1202        n = noop = sendv = 1;
  1203        push();
  1204      }
  1205    }
  1206    if (sp) {                     /* last argument pushed (attr=) */
  1207      if (sendv) {
  1208        gen_move(s, cursp(), sp, 0);
  1209        pop();
  1210        genop_1(s, OP_ARYPUSH, cursp());
  1211        push();
  1212      }
  1213      else {
  1214        gen_move(s, cursp(), sp, 0);
  1215        push();
  1216        n++;
  1217      }
  1218    }
  1219    if (tree && tree->cdr) {
  1220      noop = 1;
  1221      codegen(s, tree->cdr, VAL);
  1222      pop();
  1223      blk = 1;
  1224    }
  1225    push();pop();
  1226    pop_n(n+1);
  1227    {
  1228      mrb_int symlen;
  1229      const char *symname = mrb_sym_name_len(s->mrb, sym, &symlen);
  1230
  1231      if (!noop && symlen == 1 && symname[0] == '+' && n == 1)  {
  1232        gen_addsub(s, OP_ADD, cursp());
  1233      }
  1234      else if (!noop && symlen == 1 && symname[0] == '-' && n == 1)  {
  1235        gen_addsub(s, OP_SUB, cursp());
  1236      }
  1237      else if (!noop && symlen == 1 && symname[0] == '*' && n == 1)  {
  1238        genop_1(s, OP_MUL, cursp());
  1239      }
  1240      else if (!noop && symlen == 1 && symname[0] == '/' && n == 1)  {
  1241        genop_1(s, OP_DIV, cursp());
  1242      }
  1243      else if (!noop && symlen == 1 && symname[0] == '<' && n == 1)  {
  1244        genop_1(s, OP_LT, cursp());
  1245      }
  1246      else if (!noop && symlen == 2 && symname[0] == '<' && symname[1] == '=' && n == 1)  {
  1247        genop_1(s, OP_LE, cursp());
  1248      }
  1249      else if (!noop && symlen == 1 && symname[0] == '>' && n == 1)  {
  1250        genop_1(s, OP_GT, cursp());
  1251      }
  1252      else if (!noop && symlen == 2 && symname[0] == '>' && symname[1] == '=' && n == 1)  {
  1253        genop_1(s, OP_GE, cursp());
  1254      }
  1255      else if (!noop && symlen == 2 && symname[0] == '=' && symname[1] == '=' && n == 1)  {
  1256        genop_1(s, OP_EQ, cursp());
  1257      }
  1258      else {
  1259        int idx = new_sym(s, sym);
  1260
  1261        if (sendv) {
  1262          genop_2(s, blk ? OP_SENDVB : OP_SENDV, cursp(), idx);
  1263        }
  1264        else {
  1265          genop_3(s, blk ? OP_SENDB : OP_SEND, cursp(), idx, n);
  1266        }
  1267      }
  1268    }
  1269    if (safe) {
  1270      dispatch(s, skip);
  1271    }
  1272    if (val) {
  1273      push();
  1274    }
